-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.site_day(t timestamp with time zone)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select ((t at time zone 'America/Santiago') - interval '4 hours')::date;
$function$;

grant execute on function public.site_day(t timestamp with time zone) to service_role;
